// Chapter 2 and 2b cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch2 and ch2b).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['three-one-four-cart', [["Dutch taps the cart wall", "You can't sleep. On either side"], "What does it mean?", "She said it was pi", "It's the start of pi", "Says so in the diary", "The next night, he taps first"]],
    ['unmake-it', [["Kai pulls off his glove", "You catch them up by the well"], "One touch. I take it off you", "You didn't ask me what I want", "He doesn't understand yet", "No, Kai.", "he's angry about it for a day"]],
    ['sunlight', [["The marsh path, at noon", "You find them on the marsh path"], "People look at the eye first", "Your hand is a paw", "six babies with it", "laughs out loud, once"]],
    ['floor-seven', ["Floor 7. The lift opens", "They're prayers. All of them.", "That clerk gave up", "Then we find out why", "somewhere at the bottom of all this"]],
    ['uptima-in-chains', ["At the bottom of the Prayer Vault", "Freya put me here", "I have no grants left", "Give me one reason", "Nobody gets left in there", "Mira breaks the chain"], [3]],
    ['two-prayers', ["Mira finds two prayers", "Her own, still sealed", "signed by Brother Anselm", "He was there", "Then he's alive"]],
    ['freya-visits', ["Freya visits the camp", "Oh good, you found her", "Tilly could be here tonight", "Please leave", "Freya leaves"], [3], {1: ['freya-projection', 50.1, 32, 34], 2: ['freya-back', 50.3, 13, 55]}],
    ['tilly', ["The night after the burning field", "better off hating a beast", "I was raised by the man", "won't need someone who's right", "How old were you?", "Mira does the sum"]],
    ['the-dispatches', ["HALE'S REPORT: \"The beast", "Your man never stood a chance", "The ones on the stair are", "Yes.", "Okay.", "doesn't say anything else"]],
    ['hale-escapes', ["Hale runs up the tower", "Tilly stays on the town floor", "I heard all of it", "I know."]],
    ['what-he-felt', ["Kai grabbed Mira", "he felt the stair", "Now you know.", "At the barrier, with my hand on Hana", "the twelfth Saint was watching", "Neither of them tells anyone"]],
    ['uptima-reads-the-prayer', ["Uptima opens Mira's prayer", "\"Not him. Take the rest of me, not him.\"", "I'm sorry. I didn't read it", "You'd have said no", "you'd have known someone heard you", "anyone in camp respects"]],
    ['thornwick-freed', ["In Thornwick, people take back", "They move down to the camp", "It rings for every alarm"], [1]],
    ['she-did-my-taxes', ["Kai talks about Hana for the first time", "I've been playing Hana", "I'm not your sister", "made me floss"]],
    ['the-grey-novice', ["Brother Anselm told Tilly", ["You wrote to me", "He says you tried"], "Every day.", "loses Hale's blessing", ["(Bram. It wasn", "It wasn't me, Bram"]]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
